(()=>{const root=document.getElementById(<?= json_encode($ocrRootId) ?>);if(!root||root.dataset.booted==='1')return;root.dataset.booted='1';const OCR_API_BASE=<?= json_encode($ocrApiBase) ?>;const tr=<?= json_encode($ocrT,JSON_UNESCAPED_UNICODE) ?>;const q=role=>root.querySelector(`[data-ocr-role="${role}"]`);const qa=selector=>Array.from(root.querySelectorAll(selector));const state={step:1,items:[],cropper:null,cropIndex:0,jobId:'',pollTimer:null,report:null,stores:[],mappings:{},selection:{},skipped:new Set(),createRaw:'',finalizing:false,canceling:false};const photosInput=q('photos-input');const dropzone=q('dropzone');const uploadPreviews=q('upload-previews');const uploadContinue=q('upload-continue');const cropEmpty=q('crop-empty');const cropLayout=q('crop-layout');const cropImage=q('crop-image');const cropFrame=cropImage.parentElement;class CustomOcrCropper{constructor(image,options){this.image=image;this.options=options||{};this.frame=image.parentElement;this.region=document.createElement('div');this.region.className='ocrw-crop-region';this.handles=['nw','n','ne','e','se','s','sw','w'].map(name=>{const node=document.createElement('span');node.className='ocrw-crop-handle';node.dataset.handle=name;this.region.appendChild(node);return node;});this.frame.appendChild(this.region);this.rect=null;this.boundMove=e=>this.onMove(e);this.boundUp=e=>this.onUp(e);this.boundResize=()=>{if(this.region.isConnected)this.resetFromValue(this.getValue('real'));};this.region.addEventListener('pointerdown',e=>this.onDown(e));window.addEventListener('resize',this.boundResize);this.init();if(this.options.onInitialize)this.options.onInitialize(this);}imageBox(){const f=this.frame.getBoundingClientRect();const r=this.image.getBoundingClientRect();return{x:r.left-f.left,y:r.top-f.top,w:r.width,h:r.height};}init(){const b=this.imageBox();this.rect={x:b.x,y:b.y,w:b.w,h:b.h};this.render();}render(){if(!this.rect)return;this.region.style.left=this.rect.x+'px';this.region.style.top=this.rect.y+'px';this.region.style.width=this.rect.w+'px';this.region.style.height=this.rect.h+'px';}clamp(rect){const b=this.imageBox();const min=Math.min(48,b.w,b.h);let x=Math.max(b.x,rect.x);let y=Math.max(b.y,rect.y);let w=Math.max(min,rect.w);let h=Math.max(min,rect.h);if(x+w>b.x+b.w)x=b.x+b.w-w;if(y+h>b.y+b.h)y=b.y+b.h-h;x=Math.max(b.x,x);y=Math.max(b.y,y);w=Math.min(w,b.x+b.w-x);h=Math.min(h,b.y+b.h-y);return{x,y,w,h};}onDown(e){e.preventDefault();const handle=e.target.dataset.handle||'move';this.drag={handle,startX:e.clientX,startY:e.clientY,start:{...this.rect}};this.region.setPointerCapture(e.pointerId);window.addEventListener('pointermove',this.boundMove);window.addEventListener('pointerup',this.boundUp);}onMove(e){if(!this.drag)return;const dx=e.clientX-this.drag.startX;const dy=e.clientY-this.drag.startY;let r={...this.drag.start};if(this.drag.handle==='move'){r.x+=dx;r.y+=dy;}else{if(this.drag.handle.includes('w')){r.x+=dx;r.w-=dx;}if(this.drag.handle.includes('e'))r.w+=dx;if(this.drag.handle.includes('n')){r.y+=dy;r.h-=dy;}if(this.drag.handle.includes('s'))r.h+=dy;}this.rect=this.clamp(r);this.render();}onUp(){if(!this.drag)return;this.drag=null;window.removeEventListener('pointermove',this.boundMove);window.removeEventListener('pointerup',this.boundUp);if(this.options.onCropEnd)this.options.onCropEnd(this.getValue('real'));}getValue(){const b=this.imageBox();const sx=this.image.naturalWidth/b.w;const sy=this.image.naturalHeight/b.h;return{x:Math.round((this.rect.x-b.x)*sx),y:Math.round((this.rect.y-b.y)*sy),width:Math.round(this.rect.w*sx),height:Math.round(this.rect.h*sy)};}resetFromValue(value){if(!value||!value.width||!value.height){this.init();return;}const b=this.imageBox();const sx=b.w/this.image.naturalWidth;const sy=b.h/this.image.naturalHeight;this.rect=this.clamp({x:b.x+value.x*sx,y:b.y+value.y*sy,w:value.width*sx,h:value.height*sy});this.render();}resizeTo(width,height){const value=this.getValue('real');value.width=width;value.height=height;this.resetFromValue(value);}moveTo(x,y){const value=this.getValue('real');value.x=x;value.y=y;this.resetFromValue(value);}destroy(){window.removeEventListener('resize',this.boundResize);this.region.remove();}}const cropThumbs=q('crop-thumbs');const resolveList=q('resolve-list');const resolveEmpty=q('resolve-empty');const scanWarningsWrap=q('scan-warnings-wrap');const scanWarnings=q('scan-warnings');const createStoreModal=q('create-store-modal');const createStoreInput=q('create-store-input');function tp(s,m){if(!s)return'';let out=s;Object.keys(m||{}).forEach(k=>{out=out.split('{'+k+'}').join(String(m[k]??''));});return out;}function escHtml(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}function icon(name){const icons={plus:'<svg class="ocrw-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 5v14"/><path d="M5 12h14"/></svg>',trash:'<svg class="ocrw-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v5"/><path d="M14 11v5"/></svg>'};return icons[name]||'';}function apiUrl(query=''){return `${OCR_API_BASE}${query}`;}function emitProgress(lines){if(typeof window.handleEmbeddedOCRProgress==='function')window.handleEmbeddedOCRProgress(lines);if(window.parent&&window.parent!==window)window.parent.postMessage({type:'ocr_progress',lines},'*');}function emitFinished(message){if(typeof window.handleEmbeddedOCRFinished==='function')window.handleEmbeddedOCRFinished(message,state.report||null);if(window.parent&&window.parent!==window)window.parent.postMessage({type:'ocr_finished',message},'*');}function heroTextByStep(step){const map={1:tr.hero_idle,2:tr.hero_crop,3:tr.hero_scan,4:tr.hero_resolve,5:tr.hero_report};return map[step]||tr.hero_idle;}function setHeroStatus(text){q('hero-status').textContent=text;}function pulseHeroStatus(text){setHeroStatus(text);window.clearTim