><span class="ocrw-preview-tag">${escHtml(item.isCropped?tr.step_crop:tr.photo+' '+(index+1))}</span><img src="${escHtml(previewUrl(item))}" alt="${escHtml(item.name)}"><div class="ocrw-preview-meta"><span>${escHtml(item.name)}</span><span>${index+1}</span></div></div>`).join(''):`<div class="ocrw-empty" style="grid-column:1/-1;">${escHtml(tr.no_files)}</div>`;}function saveCurrentCropData(){if(state.cropper&&state.items[state.cropIndex])state.items[state.cropIndex].cropData=state.cropper.getValue('real');}function destroyCropper(){if(state.cropper){state.cropper.destroy();state.cropper=null;}}function updateCropBadge(){q('crop-progress-badge').textContent=`${state.items.length?state.cropIndex+1:0}/${state.items.length}`;}function cropprOptions(item){return{startSize:[100,100,'%'],returnMode:'real',onInitialize(instance){if(item.cropTouched&&item.cropData){instance.resizeTo(item.cropData.width,item.cropData.height);instance.moveTo(item.cropData.x,item.cropData.y);}},onCropEnd(data){if(state.items[state.cropIndex]===item){item.cropTouched=true;item.cropData=data;}}};}function selectCropIndex(index){if(!state.items.length)return;saveCurrentCropData();state.cropIndex=Math.max(0,Math.min(index,state.items.length-1));const item=state.items[state.cropIndex];updateCropBadge();q('crop-current-name').textContent=item.name;q('crop-current-note').textContent=item.isCropped?tr.apply_crop:tr.crop_hint;qa('.ocrw-thumb').forEach((node,i)=>node.classList.toggle('is-active',i===state.cropIndex));destroyCropper();cropImage.onload=()=>{state.cropper=new CustomOcrCropper(cropImage,cropprOptions(item));};const src=previewUrl(item);if(cropImage.src!==src){cropImage.src=src;}else if(cropImage.complete){state.cropper=new CustomOcrCropper(cropImage,cropprOptions(item));}}function renderCropStep(){if(!state.items.length){cropEmpty.classList.remove('ocrw-hidden');cropLayout.classList.add('ocrw-hidden');updateCropBadge();return;}cropEmpty.classList.add('ocrw-hidden');cropLayout.classList.remove('ocrw-hidden');cropThumbs.innerHTML=state.items.map((item,index)=>`<button type="button" class="ocrw-thumb${index===state.cropIndex?' is-active':''}" data-index="${index}"><img src="${escHtml(previewUrl(item))}" alt="${escHtml(item.name)}"><div><div class="ocrw-thumb-name">${escHtml(item.name)}</div><div class="ocrw-thumb-note">${escHtml(item.isCropped?tr.apply_crop:tr.photo+' '+(index+1))}</div></div></button>`).join('');qa('.ocrw-thumb').forEach(node=>node.onclick=()=>selectCropIndex(Number(node.dataset.index)));selectCropIndex(Math.min(state.cropIndex,state.items.length-1));}function blobFromCanvas(canvas){return new Promise(resolve=>canvas.toBlob(blob=>resolve(blob),'image/jpeg',0.92));}function loadImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>resolve(image);image.onerror=reject;image.src=url;});}async function fileFromCropData(item,index){if(item.croppedBlob)return item.croppedBlob;if(!item.cropData)return item.file;const d=item.cropData;if(!d.width||!d.height)return item.file;const image=await loadImage(item.url);const canvas=document.createElement('canvas');const scale=Math.min(1,2200/Math.max(d.width,d.height));canvas.width=Math.max(1,Math.round(d.width*scale));canvas.height=Math.max(1,Math.round(d.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(image,d.x,d.y,d.width,d.height,0,0,canvas.width,canvas.height);const blob=await blobFromCanvas(canvas);return blob?new File([blob],item.file.name||('photo-'+(index+1)+'.jpg'),{type:'image/jpeg'}):item.file;}async function applyCrop(){if(!state.items.length)return;saveCurrentCropData();const item=state.items[state.cropIndex];const file=await fileFromCropData(item,state.cropIndex);if(!file)return;if(item.croppedUrl)URL.revokeObjectURL(item.croppedUrl);item.croppedBlob=file;item.croppedUrl=URL.createObjectURL(file);item.cropData=null;item.cropTouched=false;item.isCropped=true;renderUploadStep();renderCropStep();}function resetCrop(){if(!state.items.length)ret