te-raw]').forEach(button=>button.onclick=()=>openCreateStore(button.dataset.createRaw,button.dataset.createName||button.dataset.createRaw));}function renderReport(){const job=state.report||{};const records=job.records||[];const warnings=job.warnings||[];const manualAdded=Number(job.manual_added||0);const unresolved=Number((job.unresolved||[]).length);const addedCount=Number(job.added_count||records.filter(row=>row.status==='added').length);q('report-currency').textContent=`${tr.currency}: ${job.base_currency||'—'}`;q('report-auto').textContent=String(addedCount);q('report-manual').textContent=String(manualAdded);q('report-remaining').textContent=String(unresolved);renderWarningList(q('report-warnings'),warnings);const hasRows=records.length>0;q('report-empty').classList.toggle('ocrw-hidden',hasRows);q('report-table-wrap').classList.toggle('ocrw-hidden',!hasRows);q('report-tbody').innerHTML=records.map(row=>{const badge=row.status==='duplicate'?` <span class="ocrw-note">${escHtml(tr.report_duplicate||'already imported')}</span>`:'';return `<tr><td>${escHtml(row.date||'')}</td><td>${escHtml(row.store||'')}${badge}</td><td>${escHtml(Number(row.amount||0).toFixed(2))} ${escHtml(job.base_currency||'')}</td></tr>`;}).join('');}async function startRecognition(){if(!state.items.length){setStep(1);return;}saveCurrentCropData();setStep(3);const fd=new FormData();q('progress-fill').style.width='0%';q('progress-percent').textContent='0%';q('progress-text').textContent=tr.loading;scanWarningsWrap.classList.add('ocrw-hidden');scanWarnings.innerHTML='';try{for(let index=0;index<state.items.length;index++){const item=state.items[index];const file=await fileFromCropData(item,index);fd.append('photos[]',file,item.file.name||('photo-'+(index+1)+'.jpg'));}const data=await api('?api=start',{method:'POST',body:fd});if(data.status!=='ok'){q('progress-text').textContent=tp(tr.err_start,{message:data.message||tr.error});emitProgress([tp(tr.err_start,{message:data.message||tr.error})]);return;}state.jobId=data.job_id||'';q('scan-currency').textContent=`${tr.currency}: ${data.base_currency||'—'}`;emitProgress([tr.processing_title,`${tr.currency}: ${data.base_currency||'—'}`]);pollJob(state.jobId);}catch(error){q('progress-text').textContent=tp(tr.err_start,{message:error.message||tr.error});emitProgress([tp(tr.err_start,{message:error.message||tr.error})]);}}function stopPolling(){if(state.pollTimer){clearInterval(state.pollTimer);state.pollTimer=null;}}function resetFlow(message){stopPolling();state.jobId='';state.report=null;state.selection={};state.skipped=new Set();state.finalizing=false;state.canceling=false;q('progress-fill').style.width='0%';q('progress-percent').textContent='0%';q('progress-text').textContent=message||tr.loading;setStep(1);renderUploadStep();}function finishRecognition(job){state.report=job;stopPolling();if((job.unresolved||[]).length){renderResolveStep();setStep(4);return;}renderReport();setStep(5);}async function pollJob(jobId){stopPolling();const tick=async()=>{try{const data=await api(`?api=status&job_id=${encodeURIComponent(jobId)}`);if(data.status!=='ok'){q('progress-text').textContent=tr.status_error;return;}const job=data.job||{};state.report=job;setRecognitionStats(job);emitProgress([q('progress-text').textContent,...(job.warnings||[]).map(formatWarn)]);if(job.state==='done'){finishRecognition(job);}if(job.state==='canceled'){resetFlow(tr.cancel_done);emitProgress([tr.cancel_done]);return;}if(job.state==='error'){stopPolling();q('progress-text').textContent=tp(tr.err_worker,{message:job.message||tr.error});emitProgress([tp(tr.err_worker,{message:job.message||tr.error})]);await api('?api=finalize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId})}).catch(()=>{});state.jobId='';}}catch(error){q('progress-text').textContent=tp(tr.err_worker,{message:error.message||tr.error});}};await tick();state.pollTimer=setInterval(tick,1200);}function openCreateStore(raw,name){state.createRaw=raw;createStoreInput.value=name||raw||'';createStoreModal.classList.add('is-open');setTimeout(()=>{createStoreInput.focus();createStoreInput.select();},0);}function closeCreateStore(){state.createRaw='';createStoreModal.classList.remove('is-open');}async function saveCreatedStore(){const name=createStoreInput.value.trim();if(!name){createStoreInput.focus();return;}const data=await api('?api=create_store',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});if(data.status!=='ok')return;state.stores=Array.isArray(data.stores)?data.stores:state.stores;state.selection[state.createRaw]=name;state.mappings[state.createRaw]=name;closeCreateStore();renderResolveStep();pulseHeroStatus(tr.saved_store);}async function applyMappings(){const map={};Object.keys(state.selection).forEach(raw=>{if(state.selection[raw]&&!state.skipped.has(raw))map[raw]=state.selection[raw];});try{const data=await api('?api=resolve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId,map,skip:[...state.skipped]})});if(data.status!=='ok'){pulseHeroStatus(tp(tr.err_start,{message:data.message||tr.error}));return;}const status=await api(`?api=status&job_id=${encodeURIComponent(state.jobId)}`);if(status.status==='ok')state.report=status.job||state.report;renderResolveStep();pulseHeroStatus(tp(tr.mapping_saved,{count:data.added||0}));if((state.report&&state.report.unresolved||[]).length){emitProgress([tp(tr.mapping_saved,{count:data.added||0})]);return;}renderReport();setStep(5);}catch(error){pulseHeroStatus(tp(tr.err_start,{message:error.message||tr.error}));emitProgress([tp(tr.err_start,{message:error.message||tr.error})]);}}async function cancelFlow(){if(state.canceling||!state.jobId){resetFlow(tr.cancel_done);return;}state.canceling=true;const button=q('cancel-job');button.textContent=tr.cancel_busy;button.disabled=true;try{await api('?api=cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JS